### `app.module.ts`
```typescript
@Module({
  controllers: [AppController, EmrDowntimePcController],
  imports: [
    // TypeORM configuration
    TypeOrmModule.forRootAsync({
      useFactory: () => AppDbConfig,
      dataSourceFactory: async (options) => {
        const dataSource = new DataSource(options);

        // Push vector into length column type
        dataSource.driver.supportedDataTypes.push(
          'vector' as WithLengthColumnType,
        );
        dataSource.driver.withLengthColumnTypes.push(
          'vector' as WithLengthColumnType,
        );

        // Initialize datasource
        await dataSource.initialize();

        return dataSource;
      },
    }),
  ],
  providers: [
    { provide: APP_FILTER, useClass: AppExceptionFilter },
    { provide: APP_GUARD, useClass: AppGuard },
    { provide: SOCKET_IO_ADAPTER, useClass: SocketIoAdapter },
  ],
})
export class AppModule {
  constructor() {}
}
```

### `entity.ts`
```typescript
@Entity()
export class LangchainFeed extends AbstractUuidEntity<LangchainFeed> {
  @Column({ type: 'vector' as any, nullable: true }) // Use type vector here but need to cast as any, otherwise TS will show an error
  embedding_vector: number[];

  @Column({ type: 'text' })
  document_content: string;

  @Column({ type: 'text' })
  collection_name: string;

  @Column({ type: 'jsonb', nullable: true })
  extra_metadata: Record<string, any>;

  @Column({ type: 'int', nullable: true })
  chunk_size: number;

  @Column({ type: 'int', nullable: true })
  chunk_overlap: number;

  @Column({ type: 'text', nullable: true })
  group: string;

  @BeforeUpdate()
  @BeforeInsert()
  stringifyVector() {
    // Convert number array to string format, so that Postgres understands it as a vector
    // e.g. '[0.9, 0.1, 0.7]'
    if (this.embedding_vector && Array.isArray(this.embedding_vector)) {
      this.embedding_vector = JSON.stringify(this.embedding_vector) as any;
    }
  }
}
```

### `abstract-uuid-entity.ts`
```typescript
import { PrimaryColumn } from 'typeorm';
import { v7 as uuidv7 } from 'uuid';
import { AbstractEntityNoPrimary } from './entity-no-primary.abstract';

export class AbstractUuidEntity<T> extends AbstractEntityNoPrimary<T> {
  @PrimaryColumn({
    type: 'uuid',
  })
  id: string;

  constructor(entity: Partial<T>) {
    // Super entity
    super(entity);

    // Assign entity
    Object.assign(this, entity);

    // Assign UUID
    if (!this.id) {
      this.id = uuidv7();
    }
  }
}
```
